<script setup lang="ts">
import { ref, watch } from 'vue'
import { action, api, states, type Item } from '../api'
const props=defineProps<{workspace:string;kind:'document'|'wiki'|'memory'}>()
const items=ref<Item[]>([]), title=ref(''), content=ref(''), query=ref(''), mode=ref('hybrid'), results=ref<any>(null), editing=ref<Item|null>(null), confirmed=ref(false), refs=ref<string[]>([]), busy=ref(false)
const labels={document:'知识库',wiki:'Wiki',memory:'长期记忆'}
async function load(){if(!props.workspace)return;items.value=(await api(`/workspaces/${props.workspace}/knowledge/${props.kind}`)).items}
watch(()=>[props.workspace,props.kind],()=>{items.value=[];editing.value=null;content.value='';refs.value=[];results.value=null;action(load,'内容已加载')},{immediate:true})
async function save(){busy.value=true;await action(async()=>{const base=`/workspaces/${props.workspace}`; if(props.kind==='document')await api(base+'/documents','POST',{filename:title.value,content:content.value});if(props.kind==='wiki')await api(base+'/wiki'+(editing.value?'/'+editing.value.id:''),editing.value?'PATCH':'POST',{title:title.value,content:content.value,refs:refs.value,...(editing.value?{revision:editing.value.revision}:{})});if(props.kind==='memory')await api(base+'/memories','POST',{content:content.value,confirmed:confirmed.value});content.value='';title.value='';editing.value=null;refs.value=[];await load()},'已保存，重新索引后可检索');busy.value=false}
async function file(event:Event){const f=(event.target as HTMLInputElement).files?.[0];if(!f)return;if(f.size>4*1024*1024){await action(async()=>{throw new Error('文件不能超过 4 MiB')});return};busy.value=true;await action(async()=>{const data=new Uint8Array(await f.arrayBuffer());let raw='';for(const byte of data)raw+=String.fromCharCode(byte);await api(`/workspaces/${props.workspace}/documents`,'POST',{filename:f.name,content:btoa(raw),encoding:'base64'});await load()},'文档已导入，重新索引后可检索');busy.value=false;(event.target as HTMLInputElement).value=''}
async function state(item:Item,status:string){await action(async()=>{await api(`/workspaces/${props.workspace}/knowledge/${props.kind}/${item.id}`,'PATCH',{revision:item.revision,status});await load()})}
async function search(){busy.value=true;await action(async()=>{results.value=await api(`/workspaces/${props.workspace}/search`,'POST',{query:query.value,mode:mode.value})},'检索完成');busy.value=false}
async function draft(){busy.value=true;await action(async()=>{const d=await api(`/workspaces/${props.workspace}/wiki-draft`,'POST',{title:title.value||query.value,query:query.value});content.value=d.content;title.value=d.title;refs.value=d.refs},'草稿已生成，请审阅后保存');busy.value=false}
async function rollback(item:Item,target:number){await action(async()=>{await api(`/workspaces/${props.workspace}/wiki/${item.id}/rollback`,'POST',{revision:item.revision,target_revision:target});await load()},'已回滚为新修订')}
async function index(){await action(async()=>{await api(`/workspaces/${props.workspace}/index`,'POST')},'索引任务已提交')}
</script>
<template><div class="page-title"><div><h1>{{labels[kind]}}</h1><p>内容按项目隔离，引用保留来源。修改内容后重新索引。</p></div><button @click="index" :disabled="!workspace">重新索引</button></div><p v-if="!workspace" class="empty">请先添加并选择一个项目。</p><template v-else><section class="search-panel"><h2>知识检索</h2><form class="toolbar" @submit.prevent="search"><input v-model="query" required placeholder="关键词、自然语言或符号名称" aria-label="检索内容"><select v-model="mode" aria-label="检索模式"><option value="hybrid">混合检索</option><option value="keyword">关键词</option><option value="vector">向量</option><option value="symbol">代码符号</option><option value="callers">调用方</option><option value="callees">被调用方</option></select><button class="primary" :disabled="busy">检索</button><button v-if="kind==='wiki'" type="button" @click="draft" :disabled="!query||busy">生成来源草稿</button></form><div v-if="results"><p class="muted">{{results.state||'代码事实结果'}} · {{results.vector_enabled?'向量已启用':'关键词 / 代码检索'}} · 引用 {{results.ref_id}}</p><p v-if="results.vector_reindex_required" class="muted">模型配置已变化，请重新索引以启用新模型的向量检索。</p><article v-for="hit in results.items" :key="hit.chunk_id" class="hit"><h3>{{hit.source.path||hit.source.title}} <small>行 {{hit.source.line}}–{{hit.source.end_line}} · {{hit.freshness==='STALE'?'来源已变化':'当前来源'}}</small></h3><pre>{{hit.content}}</pre></article><pre v-if="!results.items">{{JSON.stringify(results,null,2)}}</pre><p v-if="results.items?.length===0" class="empty">当前范围没有命中；这不代表源码或资料中不存在。</p></div></section><div class="knowledge-columns"><section><h2>已保存内容</h2><article v-for="item in items" :key="item.id" class="entry"><h3>{{item.title}}</h3><span class="state">{{states[item.status||'']}}</span><p class="excerpt">{{item.content}}</p><div class="actions"><button v-if="kind==='wiki'&&item.status!=='deleted'" @click="editing=item;title=item.title||'';content=item.content||'';refs=item.refs||[]">编辑</button><button v-if="kind==='memory'&&item.status==='pending'" @click="state(item,'confirmed')">确认</button><button v-if="kind==='memory'&&item.status==='pending'" @click="state(item,'rejected')">拒绝</button><button v-if="item.status!=='deleted'" class="danger" @click="state(item,'deleted')">移除</button></div><details v-if="kind==='wiki'&&item.versions?.length"><summary>历史版本</summary><p v-for="v in item.versions" :key="v.revision">修订 {{v.revision}} <button @click="rollback(item,v.revision)">回滚</button></p></details></article><p v-if="!items.length" class="empty">尚无内容</p></section><section><h2>{{editing?'修订页面':'添加内容'}}</h2><form @submit.prevent="save"><label v-if="kind!=='memory'">{{kind==='document'?'文档名称':'页面标题'}}<input v-model="title" required maxlength="200"></label><label>内容<textarea v-model="content" required rows="12" :maxlength="kind==='memory'?10000:200000"></textarea></label><label v-if="kind==='memory'" class="check"><input type="checkbox" v-model="confirmed">这是已经明确确认的事实</label><p v-if="kind==='memory'" class="muted">推断默认进入待确认状态；只有确认的记忆进入检索。</p><div class="actions"><button class="primary" :disabled="busy">{{editing?'保存修订':'保存内容'}}</button><button v-if="editing" type="button" @click="editing=null;content='';title='';refs=[]">取消编辑</button></div></form><label v-if="kind==='document'" class="upload">导入文件<input type="file" accept=".txt,.md,.pdf,.docx,.rst,.csv,.json,.yaml,.yml" @change="file" :disabled="busy"><small>文本、Markdown、PDF、DOCX，最多 4 MiB；扫描 PDF 需先 OCR。</small></label></section></div></template></template>
